// Seed avatar catalog — the offline/empty-DB fallback wardrobe.
//
// The starter character is built from Kenney's "Modular Characters" pack
// (CC0, https://kenney.nl/assets/modular-characters): skin, faces, hair,
// tops, bottoms and shoes. Each file in app/public/avatar/seed/ is a
// 3360x560 walk sheet of 7 cells (idle + a 6-pose walk cycle), generated by
// app/scripts/avatar-seed/build_sheets.py. The character faces the viewer,
// so the left view is simply mirrored. One base colour per style ships;
// visitors recolour skin, hair and clothes from the palettes in
// avatarTypes.ts.
//
// Your own art uploads via the admin wardrobe (/admin/wardrobe) and takes
// priority over these seeds (DB rows win in resolveEffectiveCatalog).
//
// Why this exists: an empty or
// unreachable `avatar_assets` table must never brick the public game.
// `resolveEffectiveCatalog` guarantees `buildDefaultAvatarConfig` can
// always resolve a full outfit, so PhaserGame always mounts.

import type { AvatarAsset, Slot } from "@/data/avatarTypes";
import { buildDefaultAvatarConfig, TINTABLE_SLOTS } from "@/data/avatarTypes";

function seedAsset(
  slot: Slot,
  variant: string,
  file: string,
  name: string,
  nameAr: string
): AvatarAsset {
  return {
    id: `seed-${slot}-${variant}`,
    slot,
    name,
    nameAr,
    spriteUrl: `/avatar/seed/${file}`,
    // null = compositor mirrors spriteUrl for the left-facing frames.
    spriteLeftUrl: null,
    tintable: TINTABLE_SLOTS.has(slot),
    zOffset: 0,
    enabled: true,
    scene: null,
  };
}

