/**
 * Return a catalog that is guaranteed to resolve a default outfit.
 * If the fetched catalog already covers every required slot, it is
 * returned untouched; otherwise the seed items are merged in (appended,
 * so DB items keep priority in `buildDefaultAvatarConfig`'s first-match
 * picks and in the wardrobe UI ordering).
 */
export function resolveEffectiveCatalog(
  fetched: readonly AvatarAsset[]
): AvatarAsset[] {
  // DB rows that point into /avatar/seed/ are just mirrors of the repo's
  // placeholder files (an earlier catalog was seeded this way).
  // The repo is the source of truth for placeholders, so those rows are
  // ignored — otherwise a seed-art revamp would leave stale DB rows
  // resurrecting deleted files. Owner uploads live in the avatar-assets
  // Storage bucket (absolute URLs) and always pass through.
  const owned = fetched.filter(
    (a) => !a.spriteUrl.startsWith("/avatar/seed/")
  );
  if (buildDefaultAvatarConfig(owned)) return owned;
  return [...owned, ...SEED_AVATAR_CATALOG];
}
